INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1404-001', 'mb.contingency', 1404, 'بر اساس دیدگاه اقتضایی لارنس و لورش (Lawrence & Lorsch)، در محیط‌های با عدم‌قطعیت بالا، سازمان‌های اثربخش چه ویژگی ساختاری دارند؟', '["تمایزیافتگی بالا و یکپارچگی ضعیف","تمایزیافتگی پایین و یکپارچگی قوی","تمایزیافتگی بالا و یکپارچگی هم‌زمان قوی","تمایزیافتگی پایین و یکپارچگی ضعیف"]'::jsonb, 2, 'لارنس و لورش اثبات کردند که در محیط‌های پویا و نامطمئن، هر زیرسیستم باید تمایز بالایی برای پاسخ به بخش محیطی خود داشته باشد، اما برای حفظ هماهنگی کلی کل سازمان به سازوکارهای یکپارچگی بسیار نیرومندی نیاز است.', 'دام طراح: انتخاب گزینه تمایز بالا بدون توجه به نیاز حیاتی به یکپارچگی هم‌زمان قوی.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1404-002', 'mb.decision', 1404, 'کدام دانشمند مفهوم «عقلانیت محدود» (Bounded Rationality) و مدل تصمیم‌گیری رضایت‌بخش را در برابر مدل عقلایی کلاسیک مطرح کرد؟', '["هربرت سایمون (Herbert Simon)","ماکس وبر (Max Weber)","چستر بارنارد (Chester Barnard)","التون مایو (Elton Mayo)"]'::jsonb, 0, 'هربرت سایمون نشان داد که انسان‌ها به دلیل محدودیت‌های شناختی، زمانی و اطلاعاتی قادر به تصمیم‌گیری کاملاً بهینه (Optimizing) نیستند و به تصمیم رضایت‌بخش (Satisficing) بسنده می‌کنند.', 'دام: خلط نظریه رفتاری عقلانیت محدود سایمون با وبر که بوروکراسی آرمانی و عقلایی را توصیف می‌کرد.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1404-003', 'stats.regression', 1404, 'در رگرسیون خطی ساده، اگر ضریب تعیین (R^2) برابر ۰٫۶۴ باشد، ضریب همبستگی پیرسون (r) در صورتی که شیب خط منفی باشد چقدر است؟', '["+۰٫۸۰","-۰٫۸۰","-۰٫۴۱","-۰٫۶۴"]'::jsonb, 1, 'ضریب تعیین مجذور ضریب همبستگی است: r = +/- sqrt(R^2) = +/- sqrt(0.64) = +/- 0.80. از آنجا که علامت شیب خط رگرسیون (b1) همواره هم‌علامت با ضریب همبستگی است و شیب منفی است، r برابر ۰٫۸۰- خواهد بود.', 'دام محاسباتی: فراموش کردن اعمال علامت منفی شیب به جذر ضریب تعیین.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1404-004', 'stats.anova', 1404, 'اگر بخواهیم میانگین عملکرد سه گروه مستقل از مدیران را با هم مقایسه کنیم، کدام آزمون آماری با رعایت مفروضات پارامتریک مناسب‌تر است؟', '["آزمون t استیودنت مستقل","تحلیل واریانس یک‌طرفه (ANOVA)","آزمون ناپارامتریک من-ویتنی","آزمون مجذور کای (Chi-Square)"]'::jsonb, 1, 'برای مقایسه میانگین بیش از دو گروه مستقل (k >= 3) با داده‌های فاصله‌ای یا نسبتی و رعایت نرمال بودن و همسانی واریانس‌ها، تحلیل واریانس یک‌طرفه (One-Way ANOVA) استفاده می‌شود.', 'دام: استفاده مکرر از آزمون t که خطای نوع اول (آلفای تورمی) را به شدت افزایش می‌دهد.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1404-005', 'islamic.malik_covenant', 1404, 'در عهدنامه مالک اشتر (نامه ۵۳ نهج‌البلاغه)، امام علی (ع) اصلی‌ترین معیار در گزینش قضات و کارگزاران ارشد را چه ویژگی‌ای معرفی می‌فرمایند؟', '["برخورداری از استقلال رأی، وسعت صدر و عدم تطمیع با مدح و ثنا","سن بالا و سابقه طولانی در دیوان‌سالاری","قرابت خویشاوندی و اطاعت بی‌چون‌وچرا","توانایی جمع‌آوری حداکثر خراج در کوتاه‌مدت"]'::jsonb, 0, 'در نامه ۵۳ نهج‌البلاغه، حضرت علی (ع) ویژگی‌های قاضی را چنین برمی‌شمارند: کسی که مضیقه‌ها او را به تنگ نیاورد، خصومت‌ها او را به لجاجت نکشاند، به اندک شناخت بسنده نکند و ستایش فراوان او را نفریبد.', 'دام: خلط مفاهیم دیوان‌سالاری سنتی (سابقه صِرف) با شایسته‌سالاری و فضیلت‌های اخلاقی علوی.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1404-006', 'sm.core_competencies', 1404, 'در مدل شایستگی‌های محوری (Core Competencies) پراهالاد و همل، کدام آزمون برای احراز شایستگی محوری لحاظ می‌شود؟', '["دسترسی به بازارهای متنوع، ارزش‌آفرینی ملموس برای مشتری و دشواری در تقلید رقبا","صرفاً ثبت پتنت رسمی و داشتن دارایی‌های مشهود بالا","کاهش هزینه تولید به کمتر از میانگین صنعت","داشتن بیشترین تعداد شعب و کانال‌های سنتی توزیع"]'::jsonb, 0, 'پراهالاد و همل سه آزمون را برای شایستگی محوری تعیین کردند: ۱) پتانسیل دسترسی به تنوع وسیعی از بازارهای هدف، ۲) سهم برجسته در منافع و ارزش ادراک‌شده مشتری از محصول نهایی، و ۳) دشواری تقلید توسط رقبا.', 'دام: تمرکز صِرف بر دارایی‌های مشهود در حالی که شایستگی محوری ماهیت نامشهود و هماهنگی یادگیری جمعی دارد.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1404-007', 'sm.rbv', 1404, 'چارچوب VRIO جی بارنی (Jay Barney) به منظور ارزیابی کدام بُعد از استراتژی سازمان طراحی شده است؟', '["شناسایی تهدیدهای محیط کلان","بررسی پتانسیل منابع و قابلیت‌های درونی برای ایجاد مزیت رقابتی پایدار","بخش‌بندی آماری بازار مصرف‌کنندگان","محاسبه نرخ تنزیل جریانات نقدی پروژه‌ها"]'::jsonb, 1, 'مدل VRIO (ارزش، کمیابی، تقلیدناپذیری و سازمان‌یافتگی) ابزار اصلی درون‌نگر دیدگاه مبتنی بر منابع برای تشخیص منابع خلق‌کننده مزیت پایدار است.', 'دام: گزینه‌های مربوط به تحلیل‌های برون‌نگر مانند ۵ نیروی پورتر و PESTEL.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1404-008', 'mkt.brand', 1404, 'در مدل هرم دارایی ویژه برند کلر (CBBE)، بالاترین سطح هرم که نشان‌دهنده رابطه عاطفی و تعهد شدید مشتری است چه نام دارد؟', '["برجسته بودن برند (Salience)","هم‌آوایی و طنین برند (Brand Resonance)","تصویر برند (Imagery)","قضاوت‌های برند (Judgments)"]'::jsonb, 1, 'قله هرم دارایی برند کلر، مرحله طنین یا هم‌آوایی برند (Resonance) است که پیوند عاطفی عمیق، وفاداری رفتاری، حس تعلق به جامعه برند و مشارکت فعال را به همراه دارد.', 'دام: خلط لایه قضاوت‌ها (لایه ۳) با طنین نهایی (لایه ۴ قله هرم).', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1404-009', 'mkt.cobranding', 1404, 'استراتژی بازاریابی «پوششی / نام تجاری مشترک» (Co-Branding) معمولاً چه مزیتی در ورود به بازارهای جدید به همراه دارد؟', '["حذف کامل هزینه‌های توزیع و لجستیک","اهرم‌سازی اعتبار و پایگاه مشتریان هر دو برند برای کاهش ریسک ادراک‌شده","معافیت از پرداخت مالیات‌های ارزش افزوده","اجتناب از هرگونه رقابت در قیمت‌گذاری"]'::jsonb, 1, 'برندسازی مشترک به دو برند امکان می‌دهد از نقاط قوت و وفاداری مشتریان متقابل برای نفوذ به بازارهای جدید با ریسک کمتر ادراک‌شده از سوی خریدار استفاده کنند.', 'دام: گزینه‌های مبالغه‌آمیز مانند حذف کامل هزینه‌ها یا لغو رقابت.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1403-001', 'sm.dynamic_capabilities', 1403, 'قابلیت‌های پویا (تیس) عمدتاً برای برطرف‌کردن کدام محدودیتِ دیدگاه مبتنی بر منابع مطرح شدند؟', '["سکون و ایستایی قابلیت‌ها در مواجهه با محیط‌های به‌سرعت متغیر","تأکید بیش از حد بر مشتریان وفادار","نادیده‌گرفتن هزینه‌های تولید مقیاس","تمرکز صِرف بر بازارهای محلی"]'::jsonb, 0, 'RBV سنتی به دلیل عدم تبیین چگونگی تطبیق شایستگی‌ها در محیط‌های فناوری متلاطم مورد نقد بود؛ تیس با مطرح کردن Dynamic Capabilities (Sensing, Seizing, Transforming) این خلأ را پوشش داد.', 'دام طراح: ربط دادن نقد RBV به بهای تمام‌شده به جای پویایی محیطی.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1403-002', 'mkt.plc', 1403, 'در مرحلهٔ رشد چرخهٔ عمر محصول (PLC)، استراتژی پیشنهادی کاتلر برای رهبر بازار چیست؟', '["بهبود کیفیت، افزودن ویژگی‌ها و مدل‌های جدید و گسترش توزیع","کاهش شدید قیمت برای آغاز جنگ فرسایشی قیمتی","خروج سریع از بازار و توقف تحقیق و توسعه","حذف تمامی کانال‌های بازاریابی رابطه‌مند"]'::jsonb, 0, 'در فاز رشد، بازار در حال انبساط است؛ بنابراین حفظ رهبری با افزودن مدل‌های جدید، کیفیت بهتر و پوشش حداکثری کانال‌ها صورت می‌گیرد، نه جنگ فرسایشی قیمتی که مختص بلوغ و اشباع است.', 'دام: خلط استراتژی‌های تدافعی مرحله اشباع با فرصت‌های گسترش مرحله رشد.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1403-003', 'tech.absorptive', 1403, 'ظرفیت جذب (Absorptive Capacity) بر اساس تعریف کوهن و لوینتال بر چه پایه‌ای بنا شده است؟', '["توانایی سازمان در شناسایی، جذب و کاربست تجاری دانش بیرونی بر پایه دانش قبلی مرتبط","میزان دارایی‌های ثابت و ماشین‌آلات فیزیکی کارخانه","تعداد پرسنل استخدامی در بخش بازاریابی","صرفاً دریافت گواهینامه‌های استاندارد ایزو"]'::jsonb, 0, 'ظرفیت جذب یک توانایی فرایندی است و سازمان تنها زمانی می‌تواند از دانش بیرونی بهره گیرد که پیش‌تر دانش مرتبط را از طریق R&D در خود نهادینه کرده باشد.', 'دام: تعریف ظرفیت جذب به صورت دارایی ایستا به جای قابلیت یادگیری پویا.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1402-001', 'sm.portfolio', 1402, 'در ماتریس BCG، یک واحد کسب‌وکار استراتژیک با سهم بازار اندک در بازاری با نرخ رشد بسیار بالا چه نامیده می‌شود؟', '["علامت سؤال (Question Mark)","ستاره (Star)","گاو شیری (Cash Cow)","سگ (Dog)"]'::jsonb, 0, 'واحد با رشد بالا و سهم کم علامت سؤال است؛ این واحدها برای تبدیل به ستاره نیازمند تزریق نقدینگی بالا هستند وگرنه به دام سگ تبدیل می‌شوند.', 'دام: اشتباه گرفتن علامت سؤال با ستاره به دلیل ویژگی مشترک رشد بالای بازار.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1402-002', 'mb.contingency', 1402, 'پژوهش تاریخی جون وودوارد نشان داد تناسب کدام متغیر با ساختار سازمانی موجب افزایش اثربخشی می‌شود؟', '["فناوری تولید (تک‌بشی، تولید انبوه، فرایندی)","مساحت ساختمان اداری و کارخانه","شخصیت روانی مدیر عامل","نوسانات بورس اوراق بهادار"]'::jsonb, 0, 'وودوارد ساختارها را با پیچیدگی فنی فرایند تولید مرتبط دانست و اثبات کرد هر نوع فناوری (Unit, Mass, Process) به ساختار متناسب خود برای اثربخشی نیاز دارد.', 'دام: خلط یافته‌های وودوارد (فناوری) با یافته‌های لارنس و لورش (عدم قطعیت محیط).', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1402-003', 'inno.s_curve', 1402, 'در منحنی S فناوری فاستر، گذار به تکنولوژی نسل جدید (Discontinuity) چه هنگام رخ می‌دهد؟', '["هنگامی که فناوری فعلی به حد اشباع فیزیکی رسیده و بازدهی تلاش‌ها نزولی می‌شود","در همان ابتدای آغاز تحقیقات اولیه فناوری اول","تنها پس از ورشکستگی کامل تمامی پیشگامان صنعت","قبل از هرگونه تجاری‌سازی اولیه"]'::jsonb, 0, 'منحنی S نشان می‌دهد که با نزدیک شدن به سقف طبیعی فناوری فعلی، هزینه‌های بهبود عملکرد فزاینده شده و زمینه برای ورود فناوری ناپیوسته جدید مهیا می‌شود.', 'دام: اشتباه در تشخیص زمان تعویض منحنی‌ها و زمان‌بندی سرمایه‌گذاری.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1401-001', 'sm.rbv', 1401, 'کدام گزینه ویژگی‌های چهارگانه منبع استراتژیک در مدل اصیل بارنی (VRIN) را مشخص می‌کند؟', '["ارزش‌آفرین، کمیاب، تقلیدناپذیر و جایگزین‌ناپذیر","فراوان، ارزان، عمومی و سریع‌الانتقال","ملموس، مشهود، قابل معامله در بورس و ارزان","کوتاه‌مدت، منعطف، قابل خرید و استهلاک‌پذیر"]'::jsonb, 0, 'مدل اصیل بارنی ۱۹۹۱: Valuable, Rare, Inimitable, Non-substitutable (VRIN) که بعدها O (Organized) به آن افزوده شد.', 'دام طراح: جایگزین کردن «جایگزین‌ناپذیر» با «قابل معامله» یا «ارزان».', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1401-002', 'stats.anova', 1401, 'کدام مفروضه زیر برای اجرای آزمون ANOVA پارامتریک در مقایسه میانگین‌ها الزامی است؟', '["همسانی واریانس خطاها و توزیع نرمال متغیر وابسته در جامعه‌ها","داده‌های صرفاً اسمی در متغیر وابسته","عدم وجود هرگونه خطای تصادفی در نمونه‌گیری","اندازه مساوی مطلق در تمام دسته‌های نمونه"]'::jsonb, 0, 'مفروضات اساسی تحلیل واریانس: نرمال بودن توزیع متغیر وابسته، همسانی واریانس‌ها (Homoscedasticity) و استقلال مشاهدات است.', 'دام: گمان اینکه اندازه نمونه‌ها حتماً باید دقیقاً برابر باشد؛ آزمون برای حجم نابرابر نیز با فرمول تعمیم‌یافته قابل اجراست.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1401-003', 'inno.ambidextrous', 1401, 'سازمان دوپهلو (Ambidextrous Organization) بر اساس نظریه اورایلی و تاشمن چگونه سازماندهی می‌شود؟', '["جداسازی ساختاری واحدهای بهره‌برداری و اکتشاف با اتصال در سطح مدیران ارشد","ادغام کامل تمام فعالیت‌های روزمره و پژوهشی در یک واحد واحد","برون‌سپاری کامل تمامی فعالیت‌های اکتشافی به دانشگاه‌ها","توقف کلیه نوآوری‌های تدریجی و تمرکز صِرف بر نوآوری برهم‌زننده"]'::jsonb, 0, 'دوپهلو بودن سازمانی به معنای هم‌زمانی بهره‌برداری از کسب‌وکار فعلی (Exploitation) و اکتشاف فرصت‌های نوین (Exploration) است که با ساختارهای موازی متصل در سطح رهبری ارشد محقق می‌شود.', 'دام: گمان اینکه دوپهلو یعنی ادغام فیزیکی همه کارها در یک تیم بدون تفکیک فرهنگ و فرایند.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1400-001', 'sm.value_chain', 1400, 'در زنجیره ارزش مایکل پورتر، کدام دسته از فعالیت‌ها جزو فعالیت‌های «پشتیبانی» طبقه‌بندی می‌شوند؟', '["زیرساخت سازمان، مدیریت منابع انسانی، توسعه فناوری و تدارکات","لجستیک ورودی، عملیات تولید، لجستیک خروجی، بازاریابی و خدمات پس از فروش","صرفاً بازاریابی و فروش کالا","صرفاً بسته‌بندی نهایی و حمل کالا"]'::jsonb, 0, 'پورتر فعالیت‌ها را به دو دسته تقسیم کرد: اولیه (Inbound, Operations, Outbound, Marketing/Sales, Service) و پشتیبانی (Infrastructure, HR, Tech Development, Procurement).', 'دام: جابه‌جا کردن فعالیت‌های اولیه و پشتیبانی در گزینه‌ها.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1400-002', 'mb.structure', 1400, 'برنز و استاکر (Burns & Stalker) ساختار مناسب برای محیط‌های پایدار با فناوری تولید روتین را چه نامیدند؟', '["ساختار مکانیکی (Mechanistic)","ساختار ارگانیک (Organic)","ساختار سلولی و شبکه‌ای","ساختار موقت پروژه‌ای (Adhocracy)"]'::jsonb, 0, 'محیط‌های باثبات نیازمند ساختار مکانیکی با قوانین صریح، سلسله‌مراتب عمودی و رویه‌های استاندارد هستند.', 'دام: خلط شرایط کارکرد ساختار مکانیکی با ارگانیک.', 'unverified') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, node_id, exam_year, question_text, options, correct_option, explanation, trap_note, verification_status) VALUES ('q-1399-001', 'stats.scales', 1399, '«رتبه‌بندی عملکرد کارکنان بر اساس عالی، خوب، متوسط و ضعیف» نمونه‌ای از کدام مقیاس اندازه‌گیری است؟', '["رتبه‌ای (ترتیبی)","اسمی","فاصله‌ای","نسبتی"]'::jsonb, 0, 'مقیاس رتبه‌ای ترتیبی از کیفیت‌ها را نشان می‌دهد اما فواصل میان سطوح معین و برابر نیست.', 'دام: اشتباه گرفتن رتبه‌ای با فاصله‌ای؛ در فاصله‌ای تفاضل‌ها ارزش عددی یکسان دارند.', 'unverified') ON CONFLICT (id) DO NOTHING;
